/// <summary>
/// One purchase order as PO confirmation lists it: header, line count and total, approval and order status, and the latest confirmation number once confirmed.
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderSummary
{
    str purchId;
    str vendorAccount;
    str vendorName;
    str warehouseId;
    str deliveryDate;
    int lineCount;
    real orderTotal;
    str currencyCode;
    str approvalStatus;
    str purchStatus;
    str createdBy;
    str createdDate;
    str confirmationNumber;
}

